# Categorical syllogism
# Premise 1: All mammals are warm-blooded
# Premise 2: All dogs are mammals
def check_syllogism(category_A, category_B, category_C):
    # If all A are B, and all B are C, then all A are C
    return category_A.issubset(category_B) and category_B.issubset(category_C)

