# Transitive ordering
def find_max(comparisons):
    # comparisons: list of (greater, lesser) tuples
    # By transitivity: if a > b and b > c then a > c
    all_items = set(x for pair in comparisons for x in pair)
    for item in all_items:
        if all(item != lesser for _, lesser in comparisons if _ == item) or \
           not any(item == lesser for _, lesser in comparisons):
            if any(item == greater for greater, _ in comparisons):
                return item  # 'Alice'

